{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Baricitinib, a close structural analogue sharing the pyrrolopyrimidine core and a sulfonamide-bearing saturated ring, has an absolute oral bioavailability of 80% in healthy volunteers, directly supporting F≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Ruxolitinib, which shares the pyrrolopyrimidine heterocycle and a cyclopentane/cyclobutane-like scaffold, has an absolute oral bioavailability of 74% in human PBPK data, with other studies reporting >95%, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Erlotinib, a moderately lipophilic oral kinase inhibitor, has a measured mean absolute oral bioavailability of 59% in healthy subjects, supporting that similar drug-like molecules with this heteroaromatic system can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Sildenafil, despite significant gut-wall metabolism, still has a mean absolute oral bioavailability of 41% in healthy volunteers, supporting that even compounds with first-pass loss exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Perindopril, a small oral drug with high transferability, has an absolute oral bioavailability of about 75% in humans, supporting high F for small molecules with favorable absorption properties.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a low-MW, moderately lipophilic pyrrolopyrimidine sulfonamide closely resembling baricitinib and ruxolitinib, both of which have high absolute oral bioavailability (≈79% and 74–>95%). Additional high-transfer oral bioavailability measurements for perindopril, sildenafil, erlotinib, and others all exceed 20%. No affirmative evidence supports F<20%. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule; prediction relies on close analogues.",
    "Potential first-pass metabolism or transporter-mediated efflux specific to the query is not experimentally characterized.",
    "Formulation and food effects for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

